using System.Windows;using WPF_SEMANA02.Data;namespace WPF_SEMANA02.Views;public partial class ReporteSalidasWindow:Window{public ReporteSalidasWindow(){InitializeComponent();MostrarTodo();}private void Buscar_Click(object s,RoutedEventArgs e){var texto=txtBuscarTransportista.Text.Trim();dgSalidas.ItemsSource=string.IsNullOrWhiteSpace(texto)?AppData.Salidas:AppData.Salidas.Where(x=>!string.IsNullOrEmpty(x.NombreTransportista)&&x.NombreTransportista.Contains(texto,StringComparison.OrdinalIgnoreCase)).ToList();}private void Limpiar_Click(object s,RoutedEventArgs e){txtBuscarTransportista.Clear();MostrarTodo();}private void MostrarTodo()=>dgSalidas.ItemsSource=AppData.Salidas;private void Volver_Click(object s,RoutedEventArgs e)=>Close();}
